// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we exercise arbitrary inputs; the property concerns the owner getter
    function testFuzz_property(address maybeOwner) public {
        // keep the fuzzed address wide but non-zero helps ensure meaningful ownership interactions
        // however we do not constrain to exclude zero, because zero is a valid fuzz input

        // call owner() and capture whether it returns the same as the stored owner we expect from initialization
        // The correct contract sets owner to the deployer in initialize; however our test deployed c via new C() and
        // did not call initialize. The Ownable storage owner getter in the correct implementation returns the stored
        // owner (which is zero before initialization) — but the specified mutant changes owner() to always return zero.
        // To create a scenario where reference returns a non-zero stored owner while mutant returns zero, we must
        // initialize ownership by calling __Ownable_init via the initialize entry point. The contract's initialize
        // function is external and sets owner to msg.sender. We'll call initialize as maybeOwner using vm.prank.

        // Fund maybeOwner so it can call initialize (no value is required but harmless)
        vm.deal(maybeOwner, 1 ether);
        vm.prank(maybeOwner);
        // call initialize to set owner = maybeOwner
        // other params: credChainId_, credId_, verificationType_, protocolFeeDestination_
        // fuzzed maybeOwner used as the caller; pass wide values for other params
        c.initialize(1, 2, "v", address(0x1234));

        // Now owner() should return maybeOwner on the reference contract for all inputs
        address reportedOwner;
        bool ok;
        try c.owner() returns (address o) {
            reportedOwner = o;
            ok = true;
        } catch {
            // If owner() reverted, mark as not ok
            ok = false;
        }

        // The general rule: after initialize called by maybeOwner, owner() must return maybeOwner (and call must succeed).
        // The mutant returns address(0) instead, so the assertion will fail for those mutants for many fuzzed maybeOwner values.
        assertTrue(ok && reportedOwner == maybeOwner);
    }
}

