contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed caller address; the property: for any caller, c.owner() should equal the stored owner (initialOwner)
    // mutant returns msg.sender and thus will differ when caller != initialOwner
    function testFuzz_property(address caller) public {
