        vm.assume(caller != address(0));

        // initialize the contract with a known owner via a different EOA than the fuzzed caller
        address initialOwner = address(0xABCD);
        // fund and prank initialOwner to call initialize
        vm.deal(initialOwner, 1 ether);
        vm.prank(initialOwner);
        c.initialize(1, 2, "verif", address(0xBEEF));

