pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(0xABCD);

    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary caller address that the fuzzer will try
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be meaningful
        vm.assume(caller != address(0));
        // initialize as deployer
        vm.prank(deployer);
        c.initialize{ }(1, 2, "vtype", address(0x123));

        // Call owner() as the fuzzed caller and as the deployer to observe behavior
        // Reference property: owner() always returns the initialized owner (deployer) for ANY caller.
        // Mutant returns msg.sender, so when caller != deployer the results diverge.

        // call owner() from fuzzed caller
        bool okCaller;
        address ownerFromCaller;
        vm.prank(caller);
        try c.owner() returns (address o) {
            okCaller = true;
            ownerFromCaller = o;
        } catch {
            okCaller = false;
            ownerFromCaller = address(0);
        }

        // call owner() from deployer
        bool okDeployer;
        address ownerFromDeployer;
        vm.prank(deployer);
        try c.owner() returns (address o2) {
            okDeployer = true;
            ownerFromDeployer = o2;
        } catch {
            okDeployer = false;
            ownerFromDeployer = address(0);
        }

        // The reference contract: both calls succeed and both returned addresses equal the initialized owner (deployer).
        // The mutant: the call by `caller` will return caller (msg.sender) which differs when caller != deployer.

        // Single assertion that must hold for the reference for ALL inputs and be violated by the mutant for some input
        // We assert that when both calls succeed, the owner reported to an arbitrary caller equals the owner reported to the initialized owner (deployer).
        // This will fail for the mutant whenever caller != deployer.
        assertTrue(okCaller && okDeployer && ownerFromCaller == ownerFromDeployer);
    }
}

