pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: for every possible stored owner value, calling owner() returns the exact stored owner address.
    // Fuzz parameter: an arbitrary address newOwner (the fuzzer will supply many values).
    function testFuzz_property(address newOwner) public {
        // keep wide domain; no restriction

        // transfer ownership via initialize pattern: initialize sets owner to msg.sender, but OwnableUpgradeable's __Ownable_init
        // in C.initialize uses msg.sender. We need to simulate different stored owner values — easiest is to call transferOwnership
        // since setUp set owner to address(this) (the test contract) via c = new C(); c.initialize wasn't called, owner is unset.
        // However OwnableUpgradeable.owner() will revert if uninitialized? In this contract, constructor called _disableInitializers(),
        // so initialize must be called to set owner. We can call __Ownable_init by calling c.initialize. That function is external in C.
        // initialize(...) sets owner to msg.sender. We'll call initialize from a pranked address newOwner to set stored owner to newOwner.

        // Prepare calldata for initialize: parameters (uint256 credChainId_, uint256 credId_, string verificationType_, address protocolFeeDestination_)
        // We only need to set owner to the caller via initialize, so provide arbitrary values for others.

        // Make newOwner call initialize to become owner
        vm.prank(newOwner);
        c.initialize(1, 2, "v", address(0x1234));

        // Now read stored owner via c.owner() — the reference should return exactly newOwner.
        address reported = c.owner();

        // The property: reported equals the stored owner exactly (no bit alterations).
        // This will be true for the reference implementation for all newOwner values, and will fail for the mutant for some newOwner values
        // where the mutated cast changes bits. We assert that equality holds.
        assertTrue(reported == newOwner);
    }
}

